// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint64 _sequenceNumber) public {
        uint64 _number = 1;
        uint64 _timestamp = 2;
        uint256 _basefee = 3;
        bytes32 _hash = bytes32(uint256(4));
        bytes32 _batcherHash = bytes32(uint256(5));
        uint256 _l1FeeOverhead = 6;
        uint256 _l1FeeScalar = 7;

        vm.prank(DEPOSITOR);
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        assertTrue(c.sequenceNumber() == _sequenceNumber);
    }
}
